import { and, eq } from "drizzle-orm";

import { db } from "../../../database/index.ts";

import {
    notificationDeliveryJobs,
    notificationPreferences,
    notificationTypeEnum,
    pushSubscriptions,
} from "../../../database/schema/index.ts";

export type NotificationEventType =
(typeof notificationTypeEnum.enumValues)[number];

export interface NotificationDomainEvent {
    /**
    * Stable ID generated by the originating domain operation.
    * Reuse this ID when retrying publication of the same event.
    */
    eventId: string;
    userId: string;
    type: NotificationEventType;
    title: string;
    message: string;
    data?: Record<string, unknown>;

}

type DeliveryChannel =
    | "IN_APP"
    | "SOCKET"
    | "EMAIL"
    | "PUSH";

interface DeliveryJobInput {
    userId: string;
    channel: DeliveryChannel;
    idempotencyKey: string;
    payload: Record<string, unknown>;
}

function buildIdempotencyKey(
    eventId: string,
    userId: string,
    channel: DeliveryChannel,
): string {
    const key = `${eventId}:${userId}:${channel}`;

    if (key.length > 255) {
        throw new Error(
            "Notification idempotency key exceeds 255 characters.",
        );
    }

    return key;
}

function buildPayload(
    event: NotificationDomainEvent,
): Record<string, unknown> {
    return {
        eventId: event.eventId,
        userId: event.userId,
        type: event.type,
        title: event.title,
        message: event.message,
        ...(event.data !== undefined
        ? { data: event.data }
        : {}),
    };
}

/**

* Publishes a notification event by writing durable delivery jobs.
*
* This function does not deliver notifications itself.
* A background worker will process the persisted jobs.
*
* Re-publishing the same event with the same eventId is safe:
* unique idempotency keys prevent duplicate jobs.
  */
export async function publishNotificationEvent(
    event: NotificationDomainEvent,
): Promise<{ queued: number }> {
    if (
        !event.eventId.trim() ||
        !event.userId.trim() ||
        !event.title.trim() ||
        !event.message.trim()
    ) {
        throw new Error(
            "Notification event ID, user ID, title, and message are required.",
        );
    }

    if (
        event.eventId.length > 150 ||
        event.title.length > 200 ||
        event.message.length > 1000
    ) {
        throw new Error(
            "Notification event exceeds the allowed field lengths.",
        );
    }

    const preferenceRows = await db
        .select({
            inAppEnabled:
            notificationPreferences.inAppEnabled,
            emailEnabled:
            notificationPreferences.emailEnabled,
        })
        .from(notificationPreferences)
        .where(
            eq(
                notificationPreferences.userId,
                event.userId,
            ),
        )
        .limit(1);

    /*

    * Match the existing preference behavior:
    * * In-app history is retained.
    * * inAppEnabled controls realtime Socket.IO delivery.
    * * emailEnabled controls email delivery.
        */
    const preferences = preferenceRows[0];

    const channels: DeliveryChannel[] = ["IN_APP"];

    if (preferences?.inAppEnabled !== false) {
        channels.push("SOCKET");
    }

    if (preferences?.emailEnabled !== false) {
        channels.push("EMAIL");
    }

  /*

  * Queue push only when the user has an active subscription.
  * Phase 18 will add complete push preferences and delivery.
    */
    const activeSubscriptions = await db
        .select({
            id: pushSubscriptions.id,
        })
        .from(pushSubscriptions)
        .where(
            and(
                eq(
                    pushSubscriptions.userId,
                    event.userId,
                ),
                eq(
                    pushSubscriptions.active,
                    true,
                ),
            ),
        );

    if (
        activeSubscriptions.length > 0 &&
        activeSubscriptions.some(
            (subscription) => Boolean(subscription.id),
        )
    ) {
        channels.push("PUSH");
    }

    const payload = buildPayload(event);

    const jobs: DeliveryJobInput[] = channels.map(
        (channel) => ({
            userId: event.userId,
            channel,
            idempotencyKey: buildIdempotencyKey(
            event.eventId,
            event.userId,
            channel,
        ),
        payload,
        }),
    );

    if (jobs.length === 0) {
        return { queued: 0 };
    }

    /*

    * Insert jobs atomically.
    * Duplicate event/channel keys are ignored.
        */
    const inserted = await db
        .insert(notificationDeliveryJobs)
        .values(
            jobs.map((job) => ({
                userId: job.userId,
                channel: job.channel,
                idempotencyKey: job.idempotencyKey,
                payload: job.payload,
            })),
        )
        .onConflictDoNothing({
            target: notificationDeliveryJobs.idempotencyKey,
        })
        .returning({
            id: notificationDeliveryJobs.id,
        });

    return {
        queued: inserted.length,
    };
}
